import type { ReactElement } from 'react';
import { useTextExpansion, type TextExpansion } from './useTextExpansion';
import './styles.css';

export type Props = { text: string; maxChars: number };

export function Component({ text, maxChars }: Props): ReactElement {
  const expansion: TextExpansion = useTextExpansion(text, maxChars);

  return (
    <section data-testid="panel" className="text-panel">
      <output aria-label="Preview" className="text-preview">{expansion.preview}</output>
      {expansion.isLong && (
        <button type="button" aria-expanded={expansion.expanded} onClick={expansion.toggle}>
          {expansion.expanded ? 'Show less' : 'Show more'}
        </button>
      )}
    </section>
  );
}

